// A form submission ({ title, costCenter, monthlyAmount, note, requester, pullRequestUrl }) or a pull request
// webhook (the same fields in its body, e.g. from a CI job that sized the change): one shape for Landledger.
// The person named is not taken at their word: Landledger asks them to confirm the request in their own session.
const src = $json.body ?? $json;
const amount = Number(src.monthlyAmount ?? src.amount ?? 0);
if (!(amount > 0)) throw new Error('A monthly amount above zero is needed');
const title = String(src.title ?? '').trim();
if (title.length < 3) throw new Error('A title of 3 characters or more is needed');
const requester = String(src.requester ?? src.email ?? '').trim().toLowerCase();
if (!requester) throw new Error('Who asks? Give their Landbright email: they confirm the request in Landledger');
const pullRequestUrl = String(src.pullRequestUrl ?? src.pull_request?.html_url ?? '').trim();
return {
  title,
  costCenter: String(src.costCenter ?? '').trim().toUpperCase(),
  amount: amount.toFixed(2),
  note: String(src.note ?? '').trim(),
  requester,
  pullRequestUrl,
  source: $json.body ? 'pull request' : 'form',
  evidence: {
    lines: [{ label: title, amount: amount.toFixed(2) }],
    basis: String(src.basis ?? (pullRequestUrl ? 'Sized in the pull request' : 'Sized by the requester in the form')),
    links: pullRequestUrl ? [{ label: 'Pull request', url: pullRequestUrl }] : [],
  },
};

parameters.code:
// Trust a decision only for a request this flow raised: created by this flow's own key (createdBy against the key's
// identity), an infra_change, and recorded by a run of this workflow whose execution is the request's origin. Anything
// else (another key, a forged origin, a request this workflow never raised) is refused, whatever the webhook says.
const event = $('Landledger events').first().json;
const detail = $('Get the request').first().json;
const r = detail.request;
const me = $('Who is this flow').first().json;
const row = $input.all().map((i) => i.json).find((x) => x.request_id === r.id);
const problems = [];
if (r.createdBy?.kind !== 'key' || !me.id || r.createdBy.id !== me.id) problems.push(`raised by ${r.createdBy?.name ?? 'someone else'}, not this flow's key (${me.name ?? 'unknown'})`);
if (r.kind !== 'infra_change') problems.push(`a ${r.kind} request, not an infra_change`);
if (r.origin?.type !== 'landflow_run' || r.origin.workflowId !== $workflow.id) problems.push('its origin is another workflow');
else if (!row) problems.push('no run of this workflow raised it');
else if (row.execution_id !== r.origin.executionId) problems.push(`its origin names run ${r.origin.executionId}, but run ${row.execution_id} raised it`);
const ours = problems.length === 0;
if (ours && event.outcome === 'approved' && r.status !== 'approved') problems.push(`Landledger says it is ${r.status} now, not approved`);
const why = problems.join('; ');
// 0: approved and ours → apply; 1: rejected, cancelled or expired and ours → tell; 2: refused.
const route = !ours ? 2 : event.outcome === 'approved' ? (r.status === 'approved' ? 0 : 2) : 1;
return [{ json: { ...detail, outcome: event.outcome, decision: event.decision ?? null, ours, why, route } }];
